//! What the fisher can catch (`fishing.tsv`, generated by `research/scripts/fishing.py` from
//! the `farm_dump` EML export): the fish spawn tables, what each bait attracts, and the
//! table players fish from where no fishing spot names another.
//!
//! A catch is drawn from the table with each fish's weight multiplied by the bait's
//! `fishBooster` factor for it, so a bait catches what it attracts. The game's own fishing
//! is a minigame on the client; this is an approximation of its odds, not its code.

use std::collections::HashMap;
use std::sync::OnceLock;

const TABLE: &str = include_str!("../fishing.tsv");

#[derive(Default, Debug)]
pub struct Fishing {
    pub default_table: String,
    /// spawn table guid -> (fish, weight)
    pub tables: HashMap<String, Vec<(u32, f32)>>,
    /// bait item -> (fish, factor)
    pub baits: HashMap<u32, Vec<(u32, f32)>>,
}

fn pairs<T: std::str::FromStr>(text: &str) -> Vec<(T, f32)> {
    text.split(',')
        .filter_map(|p| {
            let (a, b) = p.split_once(':')?;
            Some((a.parse().ok()?, b.parse().ok()?))
        })
        .collect()
}

impl Fishing {
    pub fn parse(text: &str) -> Fishing {
        let mut f = Fishing::default();
        for line in text.lines() {
            let p: Vec<&str> = line.split('\t').collect();
            match (p[0], p.len()) {
                ("default", 2..) => f.default_table = p[1].into(),
                ("table", 3..) => {
                    f.tables.insert(p[1].into(), pairs(p[2]));
                }
                ("bait", 3..) => {
                    if let Ok(item) = p[1].parse() {
                        f.baits.insert(item, pairs(p[2]));
                    }
                }
                _ => {}
            }
        }
        f
    }

    pub fn is_bait(&self, item: u32) -> bool {
        self.baits.contains_key(&item)
    }

    /// The fish a bait can bring up from a table, with their weights.
    pub fn odds(&self, table: &str, bait: u32) -> Vec<(u32, f32)> {
        let Some(fish) = self.tables.get(table).or_else(|| self.tables.get(&self.default_table)) else { return Vec::new() };
        let boost = self.baits.get(&bait);
        fish.iter()
            .map(|&(item, weight)| (item, weight * boost.and_then(|b| b.iter().find(|x| x.0 == item)).map_or(0.0, |x| x.1)))
            .filter(|&(_, w)| w > 0.0)
            .collect()
    }

    /// Draws a fish; `roll` is uniform in 0..1.
    pub fn draw(&self, table: &str, bait: u32, roll: f64) -> Option<u32> {
        let odds = self.odds(table, bait);
        let total: f64 = odds.iter().map(|o| o.1 as f64).sum();
        let mut at = roll * total;
        for &(item, w) in &odds {
            at -= w as f64;
            if at < 0.0 {
                return Some(item);
            }
        }
        odds.last().map(|o| o.0)
    }
}

pub fn data() -> &'static Fishing {
    static DATA: OnceLock<Fishing> = OnceLock::new();
    DATA.get_or_init(|| Fishing::parse(TABLE))
}

/// A small xorshift generator: dice for the catches, no dependency.
pub struct Dice(u64);

impl Dice {
    pub fn new(seed: u64) -> Dice {
        Dice(seed | 1)
    }
    /// Uniform in 0..1.
    pub fn roll(&mut self) -> f64 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        (self.0 >> 11) as f64 / (1u64 << 53) as f64
    }
}

/// `keen::Guid` bytes (as in a component) in their text form.
pub fn guid_text(b: &[u8]) -> Option<String> {
    let b: [u8; 16] = b.get(..16)?.try_into().ok()?;
    let hex = |s: &[u8]| s.iter().map(|x| format!("{x:02x}")).collect::<String>();
    let rev = |s: &[u8]| s.iter().rev().copied().collect::<Vec<u8>>();
    Some(format!("{}-{}-{}-{}-{}", hex(&rev(&b[0..4])), hex(&rev(&b[4..6])), hex(&rev(&b[6..8])), hex(&b[8..10]), hex(&b[10..16])))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_generated_data_has_the_default_table_and_baits() {
        let f = data();
        assert!(f.tables.contains_key(&f.default_table));
        assert_eq!(f.baits.len(), 13);
        // the simple bait only attracts the two common fish
        let simple = 3151503945;
        let mut fish: Vec<u32> = f.odds(&f.default_table, simple).iter().map(|o| o.0).collect();
        fish.sort();
        assert_eq!(fish, vec![2004880509, 3480216747]);
        assert!(fish.contains(&f.draw(&f.default_table, simple, 0.7).unwrap()));
        assert!(f.odds(&f.default_table, 12345).is_empty(), "no bait, no fish");
    }

    #[test]
    fn draws_follow_the_weights() {
        let f = Fishing::parse("default\tt\ntable\tt\t1:10,2:30\nbait\t9\t1:1,2:1\n");
        assert_eq!(f.draw("t", 9, 0.2), Some(1));
        assert_eq!(f.draw("t", 9, 0.3), Some(2));
        assert_eq!(f.draw("unknown spot", 9, 0.9), Some(2), "unknown tables fall back to the default");
        let mut dice = Dice::new(42);
        let catches: Vec<u32> = (0..1000).filter_map(|_| f.draw("t", 9, dice.roll())).collect();
        let ones = catches.iter().filter(|&&c| c == 1).count();
        assert!((200..300).contains(&ones), "about a quarter, got {ones}");
    }

    #[test]
    fn guids_read_like_the_game_writes_them() {
        let bytes = shroudlink_sdk::guid_bytes("7ac6cdd5-f241-49ba-b0e5-d5310f8bed2d").unwrap();
        assert_eq!(guid_text(&bytes).unwrap(), "7ac6cdd5-f241-49ba-b0e5-d5310f8bed2d");
    }
}
